import javax.swing.*;import java.awt.*;import java.sql.*;
public class TransactionFrame extends JFrame{JTextField aid=new JTextField(),amt=new JTextField(),des=new JTextField();JComboBox<String> type=new JComboBox<>(new String[]{"DEPOSIT","WITHDRAW"});public TransactionFrame(){setTitle("Deposit / Withdraw");setSize(620,480);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel p=new JPanel(null);p.setBackground(new Color(230,240,255));JLabel h=new JLabel("DEPOSIT / WITHDRAW",SwingConstants.CENTER);h.setFont(new Font("Arial",1,22));h.setBounds(150,25,320,35);p.add(h);lab(p,"Account ID:",70,90);fld(p,aid,220,90);lab(p,"Type:",70,140);type.setBounds(220,140,280,30);p.add(type);lab(p,"Amount:",70,190);fld(p,amt,220,190);lab(p,"Description:",70,240);fld(p,des,220,240);JButton b=new JButton("PROCESS");b.setBounds(120,330,150,40);p.add(b);b.addActionListener(e->process());add(p);}void lab(JPanel p,String s,int x,int y){JLabel l=new JLabel(s);l.setBounds(x,y,140,30);p.add(l);}void fld(JPanel p,JTextField f,int x,int y){f.setBounds(x,y,280,30);p.add(f);}void process(){try{int id=Integer.parseInt(aid.getText().trim());double amount=Double.parseDouble(amt.getText().trim());if(amount<=0)throw new NumberFormatException();Connection c=DBConnection.getConnection();try{c.setAutoCommit(false);double balance;String st;try(PreparedStatement q=c.prepareStatement("SELECT BALANCE,STATUS FROM BANK_ACCOUNTS WHERE ACCOUNT_ID=? FOR UPDATE")){q.setInt(1,id);try(ResultSet r=q.executeQuery()){if(!r.next()){JOptionPane.showMessageDialog(this,"Account not found!");c.rollback();return;}balance=r.getDouble(1);st=r.getString(2);}}if(!"ACTIVE".equalsIgnoreCase(st)){JOptionPane.showMessageDialog(this,"Account inactive!");c.rollback();return;}String typ=type.getSelectedItem().toString();if(typ.equals("WITHDRAW")&&balance<amount){JOptionPane.showMessageDialog(this,"Insufficient balance!");c.rollback();return;}double nb=typ.equals("DEPOSIT")?balance+amount:balance-amount;try(PreparedStatement q=c.prepareStatement("UPDATE BANK_ACCOUNTS SET BALANCE=? WHERE ACCOUNT_ID=?")){q.setDouble(1,nb);q.setInt(2,id);q.executeUpdate();}try(PreparedStatement q=c.prepareStatement("INSERT INTO BANK_TRANSACTIONS VALUES(BANK_TRANSACTION_SEQ.NEXTVAL,?,?,?,SYSDATE,?)")){q.setInt(1,id);q.setString(2,typ);q.setDouble(3,amount);q.setString(4,des.getText().trim());q.executeUpdate();}c.commit();JOptionPane.showMessageDialog(this,typ+" successful!");}catch(SQLException e){c.rollback();throw e;}finally{c.close();}}catch(NumberFormatException e){JOptionPane.showMessageDialog(this,"Account ID and amount must be valid!");}catch(SQLException e){JOptionPane.showMessageDialog(this,"Database Error: "+e.getMessage());}}}
